window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d3ef96bb4cf4e44d"]={"versions": [{"id": "FIG-d3ef96bb4cf4e44d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Wertbereichs- und Arbitrierungsdiagramm (Signal-Level / Interface-Mapping-Diagramm) für Drehmomentgrenzen und Sollwerte an der Kupplungsschnittstelle.</li>\n<li><strong>Funktionaler Kontext:</strong> Spezifiziert im Konzeptdokument <code>AUTOSAR_EXP_AIPowertrain</code> (Release R4.0.3) im Rahmen der standardisierten Applikationsschnittstellen (Application Interfaces) für den Antriebsstrang.</li>\n<li><strong>Technischer Zweck:</strong> Definition der Drehmoment-Arbitrierung an der physikalischen Trennstelle Kupplung (<code>Clutch</code>) zwischen Getriebesteuerung (<code>Transmission Control</code>, TC) und Antriebsstrang/Motorsteuerung (<code>Powertrain/Engine Control</code>, EMS). Das Diagramm veranschaulicht ein konkretes Interventionsszenario (Schaltphasenregelung / <em>Shift Energy Management</em>), bei dem das Fahrer-Wunschmoment durch transmissionsseitige Drehmomentbegrenzungen über getrennte Momentenpfade (Fast/Slow Path) auf einen resultierenden Kupplungsmomentsollwert gekappt wird.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Beteiligte SW-C-Akteure & Domänen</p>\n<ul class=\"fig-list\">\n<li><strong>Engine/Powertrain Management (EMS / Powertrain SW-C):</strong> Stellt Basismomente bereit, berechnet interne Vorsteuerungen (ohne Getriebeeingriff) und setzt das resultierende Ist-Kupplungsmoment um.</li>\n<li><strong>Transmission Management (Trsm / TC SW-C):</strong> Sendet koordinierende Limitierungsanforderungen (Min/Max-Limits) zur thermischen und mechanischen Lastführung der Kupplung während Schaltvorgängen.</li>\n<li><strong>Driver Interpretation (HMI / VCU SW-C):</strong> Liefert die ungefilterte Fahrerwunschanforderung.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Signale (Sender-Receiver-Kommunikation via AUTOSAR RTE)</p>\n<p class=\"fig-p\">| Signalbezeichnung (Kurz- / Alternativname) | Kommunikationsrichtung | Pfad / Typus | Semantik & Wertebereich |</p>\n<p class=\"fig-p\">| :--- | :--- | :--- | :--- |</p>\n<p class=\"fig-p\">| <code>DrvReqTqCluSlow</code> / <code>TqSlowAtCluReqdByDrvr</code> | Sender: Driver/EMS $\\rightarrow$ Receiver: Arbiter | Slow Path | Stationärer/langsamer Fahrerwunsch bezogen auf das Kupplungsmoment (z. B. Füllungspfad, Drosselklappe). |</p>\n<p class=\"fig-p\">| <code>DrvReqTqCluFast</code> / <code>TqFastAtCluReqdByDrvr</code> | Sender: Driver/EMS $\\rightarrow$ Receiver: Arbiter | Fast Path | Dynamischer/schneller Fahrerwunsch (z. B. Zündwinkel-/Einspritzpfad). Im Beispielszenario identisch mit Slow Path. |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMaxSlow</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Slow Path Limit | Oberes Momentenlimit für Schaltenergiemanagement (stationäre Reduktion). |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMaxFast</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Fast Path Limit | Oberes Momentenlimit für hochdynamische Momentenkappung. Wirkt im Beispielszenario als aktiver Begrenzer (Setpoint). |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMinSlow</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Slow Path Limit | Unteres Momentenlimit der Getriebesteuerung (nahe dem Minimalwert des Datentyps / Schubmomentgrenze). |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMinFast</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Fast Path Limit | Dynamische untere Drehmomentgrenze der Getriebesteuerung. |</p>\n<p class=\"fig-p\">| <code>PtTqCluTarGear</code> | Sender: Powertrain $\\rightarrow$ Receiver: Transmission | Prädiktion | Vorausberechnetes Kupplungsmoment für den Zielgang nach Schaltung. |</p>\n<p class=\"fig-p\">| <code>PtTqCluReqWoTrsmIntv</code> | Powertrain-intern / Interface | Vorsteuerung (Soll) | Kupplungssollmoment ohne Berücksichtigung transmissionsseitiger Eingriffe. |</p>\n<p class=\"fig-p\">| <code>PtTqCluWoTrsmIntv</code> | Powertrain-intern / Interface | Modelliert (Ist) | Tatsächliches Kupplungsmoment ohne Getriebeeingriff (verzögert gegenüber Sollwert durch Streckendynamik/Totzeit, <em>„e.g. delay“</em>). |</p>\n<p class=\"fig-p\">| <code>PtTqClu</code> / <code>EngTqActAtClu</code> | Sender: Powertrain $\\rightarrow$ Receiver: Transmission/Bus | Status (Ist) | Tatsächlich an der Kupplung anliegendes Moment (Ergebnis der Arbitrierung). |</p>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Koordinationsablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialzustand (Fahrerwunsch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Fahrer fordert über Fahrpedal ein hohes Moment an: <code>DrvReqTqCluSlow == DrvReqTqCluFast</code>.</li>\n<li>Ohne Getriebeeingriff würde das Moment <code>PtTqCluReqWoTrsmIntv</code> angefordert und zeitverzögert als <code>PtTqCluWoTrsmIntv</code> eingeregelt werden.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eingriffstrigger (Schaltbeginn im Getriebe):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Getriebesteuerung fordert zur Reduzierung der Schaltenergie eine koordinierte Momentenabsenkung an.</li>\n<li><code>TrsmTqCluMaxSlow</code> und <code>TrsmTqCluMaxFast</code> werden unter das Niveau des Fahrerwunsches abgesenkt.</li>\n<li><code>TrsmTqCluMinSlow</code> und <code>TrsmTqCluMinFast</code> verbleiben unkritisch an der unteren Grenze des Datentyps (<code>Lower limit of data type</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Arbitrierung & Sollwertgenerierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Min-Filterung (Oberer Begrenzer):</strong> Der effektive Sollwert errechnet sich über:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{Setpoint} = \\min(\\text{DrvReqTqClu}, \\text{TrsmTqCluMaxFast}, \\text{TrsmTqCluMaxSlow})$$</p>\n<ul class=\"fig-list\">\n<li>Im gezeigten Fall wird der Sollwert exakt durch die schnellwirkende Getriebeobergrenze geklemmt (<code>Setpoint = TrsmTqCluMaxFast</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Umsetzung & Rückmeldung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Powertrain regelt das Ist-Moment am Aktor Kupplung/Motor auf diesen Sollwert ein (<code>PtTqClu / EngTqActAtClu = Setpoint</code>).</li>\n<li>Über <code>PtTqCluTarGear</code> erhält das Getriebe fortlaufend modellbasierte Vorschauwerte zur Synchronisation des Kupplungsschlupfs für den nächsten Gang.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Port-Konfiguration & Datentypen:</strong></li>\n<li>Datenübertragung erfolgt über AUTOSAR Sender-Receiver-Interfaces (SR-Ports).</li>\n<li>Skalierung: Typischerweise standardisierte Drehmoment-Datentypen in Newtonmetern (<code>Nm</code>), als Festkommawert (z. B. <code>Phys = Internal * 0.1 - Offset</code>) oder Fließkomma (<code>float32</code>).</li>\n<li>Grenzwerte: Begrenzung durch <code>Upper limit of data type</code> und <code>Lower limit of data type</code> (Sättigung bei Über-/Unterlauf muss softwareseitig in den Runnable Entities abgefangen werden).</li>\n<li><strong>Pfadtrennung (Fast Path vs. Slow Path):</strong></li>\n<li>*<em>Fast Path (<code></em>Fast</code>):** Zyklische Task mit hoher Priorität und kurzer Abtastzeit (z. B. 1–2 ms oder kurbelwellensynchron). Wird im Ottomotor primär über Zündwinkelrücknahme oder Einspritzabschaltung, im E-Antrieb direkt über feldorientierte Stromregelung umgesetzt.</li>\n<li>*<em>Slow Path (<code></em>Slow</code>):** Zyklische Task mit mittlerer Priorität (z. B. 10 ms). Realisierung über Drosselklappe/Luftpfad bzw. Ladedruck. Dient zur stationären thermischen Entlastung des schnellen Pfads.</li>\n<li><strong>Laufzeit- & Konsistenzanforderungen:</strong></li>\n<li>Zur Vermeidung von Regelschwingungen und Drehmomentsprüngen an der Kupplung müssen Anforderungspaare (<code>TrsmTqCluMax<em></code> bzw. <code>DrvReqTqClu</em></code>) im selben Ausführungsintervall synchron konsumiert werden (RTE Data Consistency Mechanismen wie <code>Rte_IRead</code> / <code>Rte_IWrite</code> bzw. Implicit Inter-Runnable Variables nutzen).</li>\n<li>Bei Kommunikationsverlust (z. B. Time-out des Getriebe-Steuergeräts auf dem CAN/FlexRay/Ethernet-Bus via Com-Modul) müssen die Limits über Initial-/Ersatzwerte automatisch auf <code>Upper limit of data type</code> defaulten, um ungewolltes Blockieren des Fahrerwunsches zu verhindern.</li>\n</ul>"}, {"id": "FIG-92d46d6f7341da5d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Wertbereichs- und Arbitrierungsdiagramm (Signal-Level / Interface-Mapping-Diagramm) für Drehmomentgrenzen und Sollwerte an der Kupplungsschnittstelle.</li>\n<li><strong>Funktionaler Kontext:</strong> Spezifiziert im Konzeptdokument <code>AUTOSAR_EXP_AIPowertrain</code> (Release R4.0.3) im Rahmen der standardisierten Applikationsschnittstellen (Application Interfaces) für den Antriebsstrang.</li>\n<li><strong>Technischer Zweck:</strong> Definition der Drehmoment-Arbitrierung an der physikalischen Trennstelle Kupplung (<code>Clutch</code>) zwischen Getriebesteuerung (<code>Transmission Control</code>, TC) und Antriebsstrang/Motorsteuerung (<code>Powertrain/Engine Control</code>, EMS). Das Diagramm veranschaulicht ein konkretes Interventionsszenario (Schaltphasenregelung / <em>Shift Energy Management</em>), bei dem das Fahrer-Wunschmoment durch transmissionsseitige Drehmomentbegrenzungen über getrennte Momentenpfade (Fast/Slow Path) auf einen resultierenden Kupplungsmomentsollwert gekappt wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Beteiligte SW-C-Akteure & Domänen</p>\n<ul class=\"fig-list\">\n<li><strong>Engine/Powertrain Management (EMS / Powertrain SW-C):</strong> Stellt Basismomente bereit, berechnet interne Vorsteuerungen (ohne Getriebeeingriff) und setzt das resultierende Ist-Kupplungsmoment um.</li>\n<li><strong>Transmission Management (Trsm / TC SW-C):</strong> Sendet koordinierende Limitierungsanforderungen (Min/Max-Limits) zur thermischen und mechanischen Lastführung der Kupplung während Schaltvorgängen.</li>\n<li><strong>Driver Interpretation (HMI / VCU SW-C):</strong> Liefert die ungefilterte Fahrerwunschanforderung.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Signale (Sender-Receiver-Kommunikation via AUTOSAR RTE)</p>\n<p class=\"fig-p\">| Signalbezeichnung (Kurz- / Alternativname) | Kommunikationsrichtung | Pfad / Typus | Semantik & Wertebereich |</p>\n<p class=\"fig-p\">| :--- | :--- | :--- | :--- |</p>\n<p class=\"fig-p\">| <code>DrvReqTqCluSlow</code> / <code>TqSlowAtCluReqdByDrvr</code> | Sender: Driver/EMS $\\rightarrow$ Receiver: Arbiter | Slow Path | Stationärer/langsamer Fahrerwunsch bezogen auf das Kupplungsmoment (z. B. Füllungspfad, Drosselklappe). |</p>\n<p class=\"fig-p\">| <code>DrvReqTqCluFast</code> / <code>TqFastAtCluReqdByDrvr</code> | Sender: Driver/EMS $\\rightarrow$ Receiver: Arbiter | Fast Path | Dynamischer/schneller Fahrerwunsch (z. B. Zündwinkel-/Einspritzpfad). Im Beispielszenario identisch mit Slow Path. |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMaxSlow</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Slow Path Limit | Oberes Momentenlimit für Schaltenergiemanagement (stationäre Reduktion). |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMaxFast</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Fast Path Limit | Oberes Momentenlimit für hochdynamische Momentenkappung. Wirkt im Beispielszenario als aktiver Begrenzer (Setpoint). |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMinSlow</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Slow Path Limit | Unteres Momentenlimit der Getriebesteuerung (nahe dem Minimalwert des Datentyps / Schubmomentgrenze). |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMinFast</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Fast Path Limit | Dynamische untere Drehmomentgrenze der Getriebesteuerung. |</p>\n<p class=\"fig-p\">| <code>PtTqCluTarGear</code> | Sender: Powertrain $\\rightarrow$ Receiver: Transmission | Prädiktion | Vorausberechnetes Kupplungsmoment für den Zielgang nach Schaltung. |</p>\n<p class=\"fig-p\">| <code>PtTqCluReqWoTrsmIntv</code> | Powertrain-intern / Interface | Vorsteuerung (Soll) | Kupplungssollmoment ohne Berücksichtigung transmissionsseitiger Eingriffe. |</p>\n<p class=\"fig-p\">| <code>PtTqCluWoTrsmIntv</code> | Powertrain-intern / Interface | Modelliert (Ist) | Tatsächliches Kupplungsmoment ohne Getriebeeingriff (verzögert gegenüber Sollwert durch Streckendynamik/Totzeit, <em>„e.g. delay“</em>). |</p>\n<p class=\"fig-p\">| <code>PtTqClu</code> / <code>EngTqActAtClu</code> | Sender: Powertrain $\\rightarrow$ Receiver: Transmission/Bus | Status (Ist) | Tatsächlich an der Kupplung anliegendes Moment (Ergebnis der Arbitrierung). |</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialzustand (Fahrerwunsch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Fahrer fordert über Fahrpedal ein hohes Moment an: <code>DrvReqTqCluSlow == DrvReqTqCluFast</code>.</li>\n<li>Ohne Getriebeeingriff würde das Moment <code>PtTqCluReqWoTrsmIntv</code> angefordert und zeitverzögert als <code>PtTqCluWoTrsmIntv</code> eingeregelt werden.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eingriffstrigger (Schaltbeginn im Getriebe):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Getriebesteuerung fordert zur Reduzierung der Schaltenergie eine koordinierte Momentenabsenkung an.</li>\n<li><code>TrsmTqCluMaxSlow</code> und <code>TrsmTqCluMaxFast</code> werden unter das Niveau des Fahrerwunsches abgesenkt.</li>\n<li><code>TrsmTqCluMinSlow</code> und <code>TrsmTqCluMinFast</code> verbleiben unkritisch an der unteren Grenze des Datentyps (<code>Lower limit of data type</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Arbitrierung & Sollwertgenerierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Min-Filterung (Oberer Begrenzer):</strong> Der effektive Sollwert errechnet sich über:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{Setpoint} = \\min(\\text{DrvReqTqClu}, \\text{TrsmTqCluMaxFast}, \\text{TrsmTqCluMaxSlow})$$</p>\n<ul class=\"fig-list\">\n<li>Im gezeigten Fall wird der Sollwert exakt durch die schnellwirkende Getriebeobergrenze geklemmt (<code>Setpoint = TrsmTqCluMaxFast</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Umsetzung & Rückmeldung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Powertrain regelt das Ist-Moment am Aktor Kupplung/Motor auf diesen Sollwert ein (<code>PtTqClu / EngTqActAtClu = Setpoint</code>).</li>\n<li>Über <code>PtTqCluTarGear</code> erhält das Getriebe fortlaufend modellbasierte Vorschauwerte zur Synchronisation des Kupplungsschlupfs für den nächsten Gang.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Port-Konfiguration & Datentypen:</strong></li>\n<li>Datenübertragung erfolgt über AUTOSAR Sender-Receiver-Interfaces (SR-Ports).</li>\n<li>Skalierung: Typischerweise standardisierte Drehmoment-Datentypen in Newtonmetern (<code>Nm</code>), als Festkommawert (z. B. <code>Phys = Internal * 0.1 - Offset</code>) oder Fließkomma (<code>float32</code>).</li>\n<li>Grenzwerte: Begrenzung durch <code>Upper limit of data type</code> und <code>Lower limit of data type</code> (Sättigung bei Über-/Unterlauf muss softwareseitig in den Runnable Entities abgefangen werden).</li>\n<li><strong>Pfadtrennung (Fast Path vs. Slow Path):</strong></li>\n<li>*<em>Fast Path (<code></em>Fast</code>):** Zyklische Task mit hoher Priorität und kurzer Abtastzeit (z. B. 1–2 ms oder kurbelwellensynchron). Wird im Ottomotor primär über Zündwinkelrücknahme oder Einspritzabschaltung, im E-Antrieb direkt über feldorientierte Stromregelung umgesetzt.</li>\n<li>*<em>Slow Path (<code></em>Slow</code>):** Zyklische Task mit mittlerer Priorität (z. B. 10 ms). Realisierung über Drosselklappe/Luftpfad bzw. Ladedruck. Dient zur stationären thermischen Entlastung des schnellen Pfads.</li>\n<li><strong>Laufzeit- & Konsistenzanforderungen:</strong></li>\n<li>Zur Vermeidung von Regelschwingungen und Drehmomentsprüngen an der Kupplung müssen Anforderungspaare (<code>TrsmTqCluMax<em></code> bzw. <code>DrvReqTqClu</em></code>) im selben Ausführungsintervall synchron konsumiert werden (RTE Data Consistency Mechanismen wie <code>Rte_IRead</code> / <code>Rte_IWrite</code> bzw. Implicit Inter-Runnable Variables nutzen).</li>\n<li>Bei Kommunikationsverlust (z. B. Time-out des Getriebe-Steuergeräts auf dem CAN/FlexRay/Ethernet-Bus via Com-Modul) müssen die Limits über Initial-/Ersatzwerte automatisch auf <code>Upper limit of data type</code> defaulten, um ungewolltes Blockieren des Fahrerwunsches zu verhindern.</li>\n</ul>"}, {"id": "FIG-f2465abd01202498", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Wertbereichs- und Arbitrierungsdiagramm (Signal-Level / Interface-Mapping-Diagramm) für Drehmomentgrenzen und Sollwerte an der Kupplungsschnittstelle.</li>\n<li><strong>Funktionaler Kontext:</strong> Spezifiziert im Konzeptdokument <code>AUTOSAR_EXP_AIPowertrain</code> (Release R4.0.3) im Rahmen der standardisierten Applikationsschnittstellen (Application Interfaces) für den Antriebsstrang.</li>\n<li><strong>Technischer Zweck:</strong> Definition der Drehmoment-Arbitrierung an der physikalischen Trennstelle Kupplung (<code>Clutch</code>) zwischen Getriebesteuerung (<code>Transmission Control</code>, TC) und Antriebsstrang/Motorsteuerung (<code>Powertrain/Engine Control</code>, EMS). Das Diagramm veranschaulicht ein konkretes Interventionsszenario (Schaltphasenregelung / <em>Shift Energy Management</em>), bei dem das Fahrer-Wunschmoment durch transmissionsseitige Drehmomentbegrenzungen über getrennte Momentenpfade (Fast/Slow Path) auf einen resultierenden Kupplungsmomentsollwert gekappt wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Beteiligte SW-C-Akteure & Domänen</p>\n<ul class=\"fig-list\">\n<li><strong>Engine/Powertrain Management (EMS / Powertrain SW-C):</strong> Stellt Basismomente bereit, berechnet interne Vorsteuerungen (ohne Getriebeeingriff), berechnet Prädiktionen / virtuelle Fahrerwünsche für den Zielzustand und setzt das resultierende Kupplungsmoment um.</li>\n<li><strong>Transmission Management (Trsm / TC SW-C):</strong> Sendet koordinierende Limitierungsanforderungen (Min/Max-Limits) zur Lastführung der Kupplung während Schaltvorgängen.</li>\n<li><strong>Driver Interpretation (HMI / VCU SW-C):</strong> Liefert die ungefilterte Fahrerwunschanforderung getrennt für Slow- und Fast-Path.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Signale (Sender-Receiver-Kommunikation via AUTOSAR RTE)</p>\n<p class=\"fig-p\">| Signalbezeichnung (Kurz- / Alternativname) | Kommunikationsrichtung | Pfad / Typus | Semantik & Wertebereich |</p>\n<p class=\"fig-p\">| :--- | :--- | :--- | :--- |</p>\n<p class=\"fig-p\">| <code>DrvReqTqCluSlow</code> / <code>TqSlowAtCluReqdByDrvr</code> | Sender: Driver/EMS $\\rightarrow$ Receiver: Arbiter | Slow Path | Stationärer/langsamer Fahrerwunsch bezogen auf das Kupplungsmoment (<code>Driver Request of Clutch Torque (Slow Path)</code>). |</p>\n<p class=\"fig-p\">| <code>DrvReqTqCluFast</code> / <code>TqFastAtCluReqdByDrvr</code> | Sender: Driver/EMS $\\rightarrow$ Receiver: Arbiter | Fast Path | Dynamischer/schneller Fahrerwunsch bezogen auf das Kupplungsmoment (<code>Driver Request of Torque at Clutch Fast Path</code>). Im Beispielszenario identisch mit Slow Path. |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMaxSlow</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Slow Path Limit | Oberes Momentenlimit für Schaltenergiemanagement auf dem langsamen Pfad. |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMaxFast</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Fast Path Limit | Oberes Momentenlimit für Schaltenergiemanagement auf dem schnellen Pfad. Wirkt im Beispielszenario als aktiver Begrenzer (Setpoint). |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMinSlow</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Slow Path Limit | Unteres Momentenlimit der Getriebesteuerung auf dem langsamen Pfad (nahe Datentyp-Untergrenze). |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMinFast</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Fast Path Limit | Unteres Momentenlimit der Getriebesteuerung auf dem schnellen Pfad. |</p>\n<p class=\"fig-p\">| <code>PtTqCluTarGear</code> / <code>PtDrvReqTqCluVirtEngSpd</code> | Sender: Powertrain $\\rightarrow$ Receiver: Transmission | Prädiktion / Virtueller Fahrerwunsch | Vorausberechnetes Kupplungsmoment für den Zielgang (<code>Predicted Torque at Clutch at Target Gear</code>) bzw. virtueller Fahrerwunsch an der Kupplung bei Zieldrehzahl (<code>Virtual Driver Request of Torque at Clutch at Target Speed</code>). |</p>\n<p class=\"fig-p\">| <code>PtTqCluReqWoTrsmIntv</code> | Powertrain-intern / Interface | Vorsteuerung (Soll) | Angeforderter Kupplungssollwert ohne Getriebeeingriff (<code>Requested Torque at Clutch without Transmission Intervention</code>). |</p>\n<p class=\"fig-p\">| <code>PtTqCluWoTrsmIntv</code> | Powertrain-intern / Interface | Modelliert (Ist) | Kupplungsmoment ohne Getriebeeingriff (<code>Torque at Clutch without Transmission Intervention</code>), verzögert gegenüber Sollwert durch Streckendynamik (<code>e.g. delay</code>). |</p>\n<p class=\"fig-p\">| <code>PtTqClu</code> / <code>EngTqActAtClu</code> | Sender: Powertrain $\\rightarrow$ Receiver: System | Resultierendes Moment | Wirksames Kupplungsmoment (<code>Torque at Clutch</code>), das auf den durch die Begrenzung vorgegebenen Sollwert (<code>Setpoint</code>) eingeregelt wird. |</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm illustriert beispielhaft ein Getriebeeingriffsszenario während eines Gangwechsels:</p>\n<ol class=\"fig-list\">\n<li><strong>Fahrerwunsch (Ausgangslage):</strong> Der Fahrer fordert über beide Drehmomentpfade (<code>DrvReqTqCluSlow</code> und <code>DrvReqTqCluFast</code>) identische Momentenwerte an.</li>\n<li><strong>Ungestörte Drehmomenttrajektorie:</strong> Ohne Getriebeeingriff steuert die Motorsteuerung den Vorsteuersollwert <code>PtTqCluReqWoTrsmIntv</code> an. Das Kupplungsmoment ohne Getriebeeingriff <code>PtTqCluWoTrsmIntv</code> folgt diesem Sollwert mit dynamischer Verzögerung (<code>e.g. delay</code>).</li>\n<li><strong>Prädiktion für Zielgang / Zieldrehzahl:</strong> Parallel stellt die Powertrain-Steuerung das vorausberechnete Zielmoment bzw. den virtuellen Fahrerwunsch über <code>PtTqCluTarGear</code> / <code>PtDrvReqTqCluVirtEngSpd</code> bereit.</li>\n<li><strong>Transmissionsintervention:</strong> Zur Begrenzung der Kupplungsbelastung fordert das Getriebesteuergerät eine Momentenreduktion an. Die unteren Grenzwerte (<code>TrsmTqCluMinSlow</code>, <code>TrsmTqCluMinFast</code>) liegen am unteren Grenzwert des Datentyps (<code>Lower limit of data type</code>). Die oberen Grenzwerte werden reduziert: <code>TrsmTqCluMaxSlow</code> auf einen mittleren Wert, <code>TrsmTqCluMaxFast</code> auf ein niedrigeres Niveau.</li>\n<li><strong>Arbitrierung & Sollwertbildung (Setpoint):</strong> Das resultierende Kupplungsmoment wird durch das Begrenzungslimit des schnellen Pfades (<code>TrsmTqCluMaxFast</code>) gekappt. Das tatsächliche Kupplungsmoment <code>PtTqClu</code> / <code>EngTqActAtClu</code> wird auf diesen Sollwert eingeregelt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Port-Konfiguration & Datentypen:</strong></li>\n<li>Datenübertragung erfolgt über AUTOSAR Sender-Receiver-Interfaces (SR-Ports).</li>\n<li>Skalierung: Typischerweise standardisierte Drehmoment-Datentypen in Newtonmetern (<code>Nm</code>), als Festkommawert (z. B. <code>Phys = Internal * 0.1 - Offset</code>) oder Fließkomma (<code>float32</code>).</li>\n<li>Grenzwerte: Begrenzung durch <code>Upper limit of data type</code> und <code>Lower limit of data type</code> (Sättigung bei Über-/Unterlauf muss softwareseitig in den Runnable Entities abgefangen werden).</li>\n<li><strong>Pfadtrennung (Fast Path vs. Slow Path):</strong></li>\n<li>*<em>Fast Path (<code></em>Fast</code>):** Zyklische Task mit hoher Priorität und kurzer Abtastzeit (z. B. 1–2 ms oder kurbelwellensynchron). Wird im Ottomotor primär über Zündwinkelrücknahme oder Einspritzabschaltung, im E-Antrieb direkt über feldorientierte Stromregelung umgesetzt.</li>\n<li>*<em>Slow Path (<code></em>Slow</code>):** Zyklische Task mit mittlerer Priorität (z. B. 10 ms). Realisierung über Drosselklappe/Luftpfad bzw. Ladedruck. Dient zur stationären thermischen Entlastung des schnellen Pfads.</li>\n<li><strong>Laufzeit- & Konsistenzanforderungen:</strong></li>\n<li>Zur Vermeidung von Regelschwingungen und Drehmomentsprüngen an der Kupplung müssen Anforderungspaare (<code>TrsmTqCluMax<em></code> bzw. <code>DrvReqTqClu</em></code>) im selben Ausführungsintervall synchron konsumiert werden (RTE Data Consistency Mechanismen wie <code>Rte_IRead</code> / <code>Rte_IWrite</code> bzw. Implicit Inter-Runnable Variables nutzen).</li>\n<li>Bei Kommunikationsverlust (z. B. Time-out des Getriebe-Steuergeräts auf dem CAN/FlexRay/Ethernet-Bus via Com-Modul) müssen die Limits über Initial-/Ersatzwerte automatisch auf <code>Upper limit of data type</code> defaulten, um ungewolltes Blockieren des Fahrerwunsches zu verhindern.</li>\n</ul>"}, {"id": "FIG-39e8a22f706637f9", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Wertbereichs- und Arbitrierungsdiagramm (Signal-Level / Interface-Mapping-Diagramm) für Drehmomentgrenzen und Sollwerte an der Kupplungsschnittstelle.</li>\n<li><strong>Funktionaler Kontext:</strong> Spezifiziert im Konzeptdokument <code>AUTOSAR_EXP_AIPowertrain</code> (Release R4.3.1) unter dem Titel <em>„Overview of AUTOSAR torque at clutch interfaces (2)“</em>.</li>\n<li><strong>Technischer Zweck:</strong> Definition der Drehmoment-Arbitrierung an der physikalischen Trennstelle Kupplung (<code>Clutch</code>) zwischen Getriebesteuerung (<code>Transmission Control</code>, TC) und Antriebsstrang/Motorsteuerung (<code>Powertrain/Engine Control</code>, EMS). Das Diagramm veranschaulicht ein Interventionsszenario bei Schalteingriffen (<em>Shift Intervention</em>), bei dem das Fahrer-Wunschmoment durch transmissionsseitige Drehmomentbegrenzungen über getrennte Momentenpfade (Fast/Slow Path) auf einen resultierenden Kupplungsmomentsollwert gekappt wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Beteiligte SW-C-Akteure & Domänen</p>\n<ul class=\"fig-list\">\n<li><strong>Engine/Powertrain Management (EMS / Powertrain SW-C):</strong> Stellt Basismomente bereit, berechnet interne Vorsteuerungen (ohne Getriebeeingriff), berechnet Prädiktionen / virtuelle Fahrerwünsche für den Zielzustand und setzt das resultierende Kupplungsmoment um.</li>\n<li><strong>Transmission Management (Trsm / TC SW-C):</strong> Sendet koordinierende Limitierungsanforderungen (Min/Max-Limits) zur Führung der Schalteingriffe (<code>Shift Intervention</code>).</li>\n<li><strong>Driver Interpretation (HMI / VCU SW-C):</strong> Liefert die ungefilterte Fahrerwunschanforderung getrennt für Slow- und Fast-Path.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Signale (Sender-Receiver-Kommunikation via AUTOSAR RTE)</p>\n<p class=\"fig-p\">| Signalbezeichnung (Kurz- / Alternativname) | Kommunikationsrichtung | Pfad / Typus | Semantik & Wertebereich |</p>\n<p class=\"fig-p\">| :--- | :--- | :--- | :--- |</p>\n<p class=\"fig-p\">| <code>DrvReqTqCluSlow</code> / <code>TqSlowAtCluReqdByDrvr</code> | Sender: Driver/EMS $\\rightarrow$ Receiver: Arbiter | Slow Path | Stationärer/langsamer Fahrerwunsch bezogen auf das Kupplungsmoment (<code>Driver Request of Clutch Torque (Slow Path)</code>). |</p>\n<p class=\"fig-p\">| <code>DrvReqTqCluFast</code> / <code>TqFastAtCluReqdByDrvr</code> | Sender: Driver/EMS $\\rightarrow$ Receiver: Arbiter | Fast Path | Dynamischer/schneller Fahrerwunsch bezogen auf das Kupplungsmoment (<code>Driver Request of Torque at Clutch Fast Path</code>). Im Beispielszenario identisch mit Slow Path. |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMaxSlow</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Slow Path Limit | Oberes Momentenlimit für Schalteingriffe auf dem langsamen Pfad (<code>Shift Intervention on Slow Path</code>). |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMaxFast</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Fast Path Limit | Oberes Momentenlimit für Schalteingriffe auf dem schnellen Pfad (<code>Shift Intervention on Fast Path</code>). Wirkt im Beispielszenario als aktiver Begrenzer (Setpoint). |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMinSlow</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Slow Path Limit | Unteres Momentenlimit der Getriebesteuerung für Schalteingriffe auf dem langsamen Pfad (<code>Shift Intervention on Slow Path</code>). |</p>\n<p class=\"fig-p\">| <code>TrsmTqCluMinFast</code> | Sender: Transmission $\\rightarrow$ Receiver: Powertrain | Fast Path Limit | Unteres Momentenlimit der Getriebesteuerung für Schalteingriffe auf dem schnellen Pfad (<code>Shift Intervention on Fast Path</code>). |</p>\n<p class=\"fig-p\">| <code>PtTqCluTarGear</code> / <code>PtDrvReqTqCluVirtEngSpd</code> | Sender: Powertrain $\\rightarrow$ Receiver: Transmission | Prädiktion / Virtueller Fahrerwunsch | Vorausberechnetes Kupplungsmoment für den Zielgang (<code>Predicted Torque at Clutch at Target Gear</code>) bzw. virtueller Fahrerwunsch an der Kupplung bei Zieldrehzahl (<code>Virtual Driver Request of Torque at Clutch at Target Speed</code>). |</p>\n<p class=\"fig-p\">| <code>PtTqCluReqWoTrsmIntv</code> | Powertrain-intern / Interface | Vorsteuerung (Soll) | Angeforderter Kupplungssollwert ohne Getriebeeingriff (<code>Requested Torque at Clutch without Transmission Intervention</code>). |</p>\n<p class=\"fig-p\">| <code>PtTqCluWoTrsmIntv</code> | Powertrain-intern / Interface | Modelliert (Ist) | Kupplungsmoment ohne Getriebeeingriff (<code>Torque at Clutch without Transmission Intervention</code>), verzögert gegenüber Sollwert durch Streckendynamik (<code>e.g. delay</code>). |</p>\n<p class=\"fig-p\">| <code>PtTqClu</code> / <code>EngTqActAtClu</code> | Sender: Powertrain $\\rightarrow$ Receiver: System | Resultierendes Moment | Wirksames Kupplungsmoment (<code>Torque at Clutch</code>), das auf den durch die Begrenzung vorgegebenen Sollwert (<code>Setpoint</code>) eingeregelt wird. |</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm illustriert beispielhaft ein Getriebeeingriffsszenario während eines Schalteingriffs (<code>Shift Intervention</code>):</p>\n<ol class=\"fig-list\">\n<li><strong>Fahrerwunsch (Ausgangslage):</strong> Der Fahrer fordert über beide Drehmomentpfade (<code>DrvReqTqCluSlow</code> und <code>DrvReqTqCluFast</code>) identische Momentenwerte an.</li>\n<li><strong>Ungestörte Drehmomenttrajektorie:</strong> Ohne Getriebeeingriff steuert die Motorsteuerung den Vorsteuersollwert <code>PtTqCluReqWoTrsmIntv</code> an. Das Kupplungsmoment ohne Getriebeeingriff <code>PtTqCluWoTrsmIntv</code> folgt diesem Sollwert mit dynamischer Verzögerung (<code>e.g. delay</code>).</li>\n<li><strong>Prädiktion für Zielgang / Zieldrehzahl:</strong> Parallel stellt die Powertrain-Steuerung das vorausberechnete Zielmoment bzw. den virtuellen Fahrerwunsch über <code>PtTqCluTarGear</code> / <code>PtDrvReqTqCluVirtEngSpd</code> bereit.</li>\n<li><strong>Transmissionsintervention (Shift Intervention):</strong> Das Getriebesteuergerät fordert eine Momentenreduktion an. Die unteren Grenzwerte (<code>TrsmTqCluMinSlow</code>, <code>TrsmTqCluMinFast</code>) liegen an der Datentyp-Untergrenze (<code>Lower limit of data type</code>). Die oberen Grenzwerte werden reduziert: <code>TrsmTqCluMaxSlow</code> auf einen mittleren Wert, <code>TrsmTqCluMaxFast</code> auf ein niedrigeres Niveau.</li>\n<li><strong>Arbitrierung & Sollwertbildung (Setpoint):</strong> Das resultierende Kupplungsmoment wird durch das Begrenzungslimit des schnellen Pfades (<code>TrsmTqCluMaxFast</code>) gekappt. Das tatsächliche Kupplungsmoment <code>PtTqClu</code> / <code>EngTqActAtClu</code> wird auf diesen Sollwert eingeregelt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Port-Konfiguration & Datentypen:</strong></li>\n<li>Datenübertragung erfolgt über AUTOSAR Sender-Receiver-Interfaces (SR-Ports).</li>\n<li>Skalierung: Typischerweise standardisierte Drehmoment-Datentypen in Newtonmetern (<code>Nm</code>), als Festkommawert (z. B. <code>Phys = Internal * 0.1 - Offset</code>) oder Fließkomma (<code>float32</code>).</li>\n<li>Grenzwerte: Begrenzung durch <code>Upper limit of data type</code> und <code>Lower limit of data type</code> (Sättigung bei Über-/Unterlauf muss softwareseitig in den Runnable Entities abgefangen werden).</li>\n<li><strong>Pfadtrennung (Fast Path vs. Slow Path):</strong></li>\n<li>*<em>Fast Path (<code></em>Fast</code>):** Zyklische Task mit hoher Priorität und kurzer Abtastzeit (z. B. 1–2 ms oder kurbelwellensynchron). Wird im Ottomotor primär über Zündwinkelrücknahme oder Einspritzabschaltung, im E-Antrieb direkt über feldorientierte Stromregelung umgesetzt.</li>\n<li>*<em>Slow Path (<code></em>Slow</code>):** Zyklische Task mit mittlerer Priorität (z. B. 10 ms). Realisierung über Drosselklappe/Luftpfad bzw. Ladedruck. Dient zur stationären thermischen Entlastung des schnellen Pfads.</li>\n<li><strong>Laufzeit- & Konsistenzanforderungen:</strong></li>\n<li>Zur Vermeidung von Regelschwingungen und Drehmomentsprüngen an der Kupplung müssen Anforderungspaare (<code>TrsmTqCluMax<em></code> bzw. <code>DrvReqTqClu</em></code>) im selben Ausführungsintervall synchron konsumiert werden (RTE Data Consistency Mechanismen wie <code>Rte_IRead</code> / <code>Rte_IWrite</code> bzw. Implicit Inter-Runnable Variables nutzen).</li>\n<li>Bei Kommunikationsverlust (z. B. Time-out des Getriebe-Steuergeräts auf dem CAN/FlexRay/Ethernet-Bus via Com-Modul) müssen die Limits über Initial-/Ersatzwerte automatisch auf <code>Upper limit of data type</code> defaulten, um ungewolltes Blockieren des Fahrerwunsches zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-d3ef96bb4cf4e44d", "to": "FIG-92d46d6f7341da5d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-92d46d6f7341da5d", "to": "FIG-f2465abd01202498", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Schnittstellensignal <code>PtTqCluTarGear</code> um alternatives Signal / Alias <code>PtDrvReqTqCluVirtEngSpd</code> (Powertrain: Virtual Driver Request of Torque at Clutch at Target Speed, in Magenta) ergänzt.</li>\n<li>Signalbezeichnung und Klartextbeschreibung von <code>PtTqClu</code> / <code>EngTqActAtClu</code>: Klartext von „Powertrain: Actual Torque at Clutch“ zu „Powertrain: Torque at Clutch“ generalisiert.</li>\n<li>Signalbezeichnung und Klartextbeschreibung von <code>PtTqCluReqWoTrsmIntv</code>: Klartext von „Powertrain: Torque at Clutch Request Without Transmission Intervention“ zu „Powertrain: Requested Torque at Clutch without Transmission Intervention“ geändert.</li>\n<li>Signalbezeichnung und Klartextbeschreibung von <code>PtTqCluWoTrsmIntv</code>: Klartext von „Powertrain: Actual Torque at Clutch Without Transmission Intervention“ zu „Powertrain: Torque at Clutch without Transmission Intervention“ geändert.</li>\n<li>Klartextbeschreibungen der Fahrerwunschanforderungen redaktionell präzisiert: „Driver Request of Clutch Torque (Slow Path)“ und „Driver Request of Torque at Clutch Fast Path“.</li>\n</ul>"}, {"from": "FIG-f2465abd01202498", "to": "FIG-39e8a22f706637f9", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Diagrammtitel „Overview of AUTOSAR torque at clutch interfaces (2)“ zentriert oberhalb des Diagramms ergänzt.</li>\n<li>Achsenbeschriftung „Torque at clutch“ an der vertikalen Drehmomentachse ergänzt.</li>\n<li>Klartextbeschreibungen der Getriebegrenzen <code>TrsmTqCluMaxFast</code>, <code>TrsmTqCluMaxSlow</code>, <code>TrsmTqCluMinSlow</code> und <code>TrsmTqCluMinFast</code>: Formulierung „for Shift Energy Management“ durch „for Shift Intervention“ ersetzt.</li>\n</ul>"}]};
